-- 208: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 6.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_208_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_208_guard;
INSERT INTO _migration_208_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_021' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_5' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should the blade be held nearly vertical when cutting a square leather edge?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It keeps the cut face perpendicular instead of undercutting the template","B. It makes the flesh-side outline smaller so paired panels nest automatically","C. It compresses the edge fibres enough to replace later burnishing","D. It produces a long feather skive along the component edge"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A vertical blade follows the template at both grain and flesh surfaces, giving accurate mating dimensions and a square edge suitable for alignment and finishing. Therefore the correct answer is A: It keeps the cut face perpendicular instead of undercutting the template.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_021' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_208_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_022' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_5' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of skiving the end of a leather strap before folding it?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Create a square step so all folded thickness ends at one abrupt line","B. Remove the grain across the fold because flesh fibres provide the main load path","C. Cut the strap to half width so it can turn around the hardware","D. Reduce bulk with a gradual taper while retaining useful fibre length"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A controlled taper lets overlapping layers fold without an obvious lump, while sufficient length and thickness avoid creating a weak hinge at the skive boundary. Therefore the correct answer is D: Reduce bulk with a gradual taper while retaining useful fibre length.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_022' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_208_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_023' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_5' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are paired leather components cut from the same verified template?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The template automatically avoids scars without inspection of the hide surface","B. Their mating outlines, notches and hole positions remain consistent","C. Both pieces then acquire the same grain direction regardless of hide placement","D. Repeated tracing compensates for a template whose finished dimensions are inaccurate"]' AND q.correct_answer IS 'B' AND q.explanation IS 'One accurate template controls repeated geometry and assembly references, although the maker must still orient each part and inspect the leather zone before cutting. Therefore the correct answer is B: Their mating outlines, notches and hole positions remain consistent.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_023' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_208_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_024' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_5' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What should be placed beneath leather when using a drive punch?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A hardened steel plate that prevents the punch from entering the support","B. A soft folded cloth that lets the work move under the impact","C. A thick offcut of finished leather intended for the same product","D. A resilient cutting board that supports a clean exit and protects the cutting edge"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A dense resilient punching surface supports the material while allowing the edge to pass through cleanly without striking steel, damaging another component or becoming unstable. Therefore the correct answer is D: A resilient cutting board that supports a clean exit and protects the cutting edge.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_024' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_021', 'topic_was_leatherwork_b004_5', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Why should the blade be held nearly vertical when cutting a square leather edge?', 'multiple_choice', NULL, '["A. It keeps the cut face perpendicular instead of undercutting the template","B. It makes the flesh-side outline smaller so paired panels nest automatically","C. It compresses the edge fibres enough to replace later burnishing","D. It produces a long feather skive along the component edge"]', 'A', 'A vertical blade follows the template at both grain and flesh surfaces, giving accurate mating dimensions and a square edge suitable for alignment and finishing. Therefore the correct answer is A: It keeps the cut face perpendicular instead of undercutting the template.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_5', 'Explain', 'AO3', NULL, NULL, 'board_waec');
